import java.util.*;

public class Main {
    int findLengthOfLCIS(int[] nums) {
        int n = nums.length;
        int best = 1;
        for (int start = 0; start < n; start++) {
            int length = 1;
            int end = start;
            while (end + 1 < n && nums[end + 1] > nums[end]) {                     // keep extending while strictly increasing
                end++;
                length++;
            }
            best = Math.max(best, length);
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.findLengthOfLCIS(new int[]{1, 3, 5, 4, 7}));
    }
}

