def find_length_of_lcis(nums):
    best = 1
    current = 1                                                             # length of the increasing streak ending at the current position
    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            current += 1                                                    # still climbing, extend the streak
        else:
            current = 1                                                     # streak broken, reset to a fresh streak of length 1
        best = max(best, current)
    return best


if __name__ == "__main__":
    print(find_length_of_lcis([1, 3, 5, 4, 7]))

